/// <summary>
/// extends SysOperationServiceController
/// </summary>
internal final class AVACRLLimitPerformanceController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    AVACRLLimitPerformanceController controller;

    controller = new AVACRLLimitPerformanceController(classStr(AVACRLLimitPerformanceService),
                                       methodStr(AVACRLLimitPerformanceService, startOperation),
                                       SysOperationExecutionMode::Synchronous);

    controller.startOperation();
}

/// <summary>
/// Returns default classDescription
/// </summary>
/// <returns>ClassDescription</returns>
protected ClassDescription defaultCaption()
{
    return "@NDX:NXACRLCalcLimitPerformance";
}
